    CConsoleCommandBase* empty = new CConsoleCommandBase;   // null buffer: no free
    delete empty;
    if (g_names != 0) { std::printf("00414fc0_TEST FAIL\n"); return 1; }
    std::printf("00414fc0_TEST PASS\n");
